const express = require('express');
const { createClient } = require('@supabase/supabase-js');
const path = require('path');

const app = express();

// Inisialisasi Supabase client menggunakan environment variables dari Vercel
const supabaseUrl = process.env.SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_KEY;
const supabase = createClient(supabaseUrl, supabaseKey);

// Middleware untuk membaca JSON
app.use(express.json());

// Sajikan file statis dari folder publik
app.use(express.static(path.join(__dirname, 'public')));

// 1. Endpoint API untuk mengambil data film
app.get('/api/movies', async (req, res) => {
  try {
    const { data, error } = await supabase
      .from('movies')
      .select('*');

    if (error) throw error;
    res.json(data);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// 2. Endpoint API untuk menangani pemesanan (Bookings)
app.get('/api/bookings', async (req, res) => {
  try {
    const { data, error } = await supabase
      .from('bookings')
      .select('*');

    if (error) throw error;
    res.json(data);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/bookings', async (req, res) => {
  try {
    const { data, error } = await supabase
      .from('bookings')
      .insert([req.body])
      .select();

    if (error) throw error;
    res.status(201).json(data[0]);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Jalankan server lokal
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server berjalan di port ${PORT}`);
});

module.exports = app;